entries[71718] = { ["name"] = "Swift Shorestrider", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A rarity amongst the tallstrider breeds of Kalimdor, but easily recognized by its pungent dead seaweed aroma.\"\nVendor:\nLandro Longshot\nLocation:\nBooty Bay" }
