entries[71949] = { ["name"] = "Tome of Burning Jewels", ["text"] = "Binds when picked up\nUse: Discovers a random Cataclysm epic gem recipe.\nRequires Cataclysm Jewelcrafting (75)" }
entries[71950] = { ["name"] = "Unbalanced Throwing Ring", ["text"] = "Binds when picked up\nUnique\nUse: Gain access to 10 Unbalanced Throwing Rings. Leaving the Ring Toss booth will void all remaining rings.\n\"Each ring feels slightly unbalanced.\"" }
entries[71951] = { ["name"] = "Banner of the Fallen", ["text"] = "This Item Begins a Quest\n\"Proof of your valor in combat. Someone at the Darkmoon Faire would be interested in this item.\"" }
