entries[71953] = { ["name"] = "Fallen Adventurer's Journal", ["text"] = "This Item Begins a Quest\n\"A journal containing stories of a fallen enemy's epic exploits. Someone at the Darkmoon Faire would be interested in seeing this.\"" }
entries[71954] = { ["name"] = "Ruthless Gladiator's Twilight Drake", ["text"] = "Binds when picked up\nUnique\nMount\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Heroes who proved their might in the gladiatorial arenas during the Cataclysm were awarded the most exceptional of the twilight drake broods.\"\nLegacy" }
