entries[71964] = { ["name"] = "Iron Stock", ["text"] = "Quest Item\nUse: Create a horseshoe. Must be used near an anvil.\n4 Charges\n\"Standard lengths of iron ready to be worked into finished products.\"" }
entries[71965] = { ["name"] = "Design: Rhinestone Sunglasses", ["text"] = "Use: Teaches you how to create Rhinestone Sunglasses.\nRequires Cataclysm Jewelcrafting (75)\n\nRhinestone Sunglasses\nCosmetic\nBinds when equipped\nHead Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:\nRequires Truegold (2), Chimera's Eye (2), Hypnotic Dust (8), Dream Emerald (2)" }
entries[71966] = { ["name"] = "Shiny Bronze Rivet", ["text"] = "Sell Price:" }
entries[71967] = { ["name"] = "Horseshoe", ["text"] = "Quest Item\nUse: Apply Baby's new horseshoes. Requires 4 Horseshoes.\n\"Workmanship worthy of royalty!\"" }
entries[71968] = { ["name"] = "Tonk Scrap", ["text"] = "Quest Item\n\"Bits of metal blown off steam tonks in combat.\"" }
entries[71969] = { ["name"] = "Darkmoon Mallet", ["text"] = "Binds when picked up\nUnique\nMain Hand\n1 - 2 Damage Speed 3.00\n(0.5 damage per second)\nSell Price:" }
entries[71970] = { ["name"] = "Darkmoon Prize Ticket", ["text"] = "Binds when picked up" }
entries[71971] = { ["name"] = "Bundle of Exotic Herbs", ["text"] = "Quest Item\nUse: Mill the herbs in this bundle to create Prophetic Ink.\n\"Fragrant and foreign, you do not recognize most of these herbs.\"" }
entries[71972] = { ["name"] = "Prophetic Ink", ["text"] = "Quest Item\nUse: Inscribe one sheet of Light Parchment to make one of Sayge's Fortunes.\n\"Magical ink rumored to reveal hints about the future.\"" }
entries[71974] = { ["name"] = "Fortune", ["text"] = "Quest Item\nUnique (5)\n\"Freshly-penned words spell out the future for those who consult Sayge.\"" }
entries[71976] = { ["name"] = "Darkmoon Prize", ["text"] = "Quest Item\n\"An oversized stuffed leather toy with shiny eyes and a winning smile.\"" }
entries[71977] = { ["name"] = "Darkmoon Craftsman's Kit", ["text"] = "Quest Item\nUse: Use a Blue Dye, 2 Shiny Baubles, and a Coarse Thread to create a Darkmoon Prize.\n\"A bag containing leather, needles, and patterns for crafting prizes.\"" }
