entries[72575] = { ["name"] = "White Riding Camel", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable White Riding Camel.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Fennimore Quigley is credited with milking the first camel and breaking the record for \"longest unintentional flight,\" all in the same afternoon.\"\nVendor:\nLandro Longshot\nLocation:\nBooty Bay" }
entries[72578] = { ["name"] = "Nectarbreeze Cider", ["text"] = "Quest Item\nUse: Spit a mouthful of cider. (3 Sec Cooldown)\n\"Sticky, sweet and cloudy. This non-alcoholic variation of the village's famous cider is deemed appropriate for children. And firefighting.\"" }
entries[72582] = { ["name"] = "Corrupted Hippogryph", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses a rideable Corrupted Hippogryph. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"It is a sad fact that even the wise and majestic hippogryph may fall prey to corruption.\"\nVendor:\nLandro Longshot\nLocation:\nBooty Bay" }
